css:
@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap');

#battle-container {
  position: absolute;
  width: 1000px;
  height: 650px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  overflow: hidden;
  font-family: 'Press Start 2P', monospace, sans-serif;
  user-select: none;
  background: #202020;
  border-radius: 12px;
  box-shadow: 0 20px 50px rgba(0,0,0,0.6);
}

#flash-overlay {
  position: absolute;
  inset: 0;
  background: #ffffff;
  z-index: 100;
  pointer-events: none;
  opacity: 0;
}

#battle-field {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, #58C8B0 0%, #A0E8D0 45%, #70C060 45%, #489838 100%);
}

#enemy-platform-wrapper {
  position: absolute;
  top: 170px;
  right: 60px;
  width: 380px;
}

#player-platform-wrapper {
  position: absolute;
  bottom: 160px;
  left: 40px;
  width: 420px;
}

.grass-oval {
  width: 100%;
  height: auto;
  filter: drop-shadow(0px 8px 10px rgba(0,0,0,0.3));
}

/* Tarjetas de estado / Banners */
.status-card {
  position: absolute;
  width: 380px;
  background: linear-gradient(180deg, #F8F8F8 0%, #E0E0E0 100%);
  border: 4px solid #282828;
  border-radius: 10px 0px 14px 0px;
  padding: 12px 16px;
  box-shadow: 4px 6px 0px rgba(0,0,0,0.4);
  z-index: 20;
  transition: transform 0.1s ease;
}

#enemy-banner {
  top: 40px;
  left: 40px;
}

#player-banner {
  bottom: 180px;
  right: 40px;
}

.card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.pkmn-name {
  font-size: 18px;
  color: #202020;
  font-weight: bold;
}

.pkmn-level {
  font-size: 15px;
  color: #404040;
}

.hp-row {
  display: flex;
  align-items: center;
  gap: 8px;
  background: #303030;
  padding: 4px 8px;
  border-radius: 6px;
}

.hp-badge {
  color: #F8B018;
  font-size: 12px;
  font-weight: bold;
}

.hp-bar-track {
  flex: 1;
  height: 12px;
  background: #181818;
  border-radius: 4px;
  overflow: hidden;
  border: 1px solid #505050;
}

.hp-bar-fill {
  height: 100%;
  width: 100%;
  background: #48D068;
  transition: width 0.3s ease, background-color 0.3s ease;
}

.hp-numbers {
  text-align: right;
  font-size: 13px;
  color: #202020;
  margin-top: 6px;
  font-weight: bold;
}

/* Panel Inferior de Acciones */
#action-panel {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 140px;
  background: #282830;
  border-top: 5px solid #F8F8F8;
  display: flex;
  padding: 12px;
  box-sizing: border-box;
  gap: 12px;
  z-index: 30;
}

#dialog-box {
  flex: 1;
  background: #F8F8F8;
  border: 4px solid #484850;
  border-radius: 10px;
  padding: 16px;
  display: flex;
  align-items: center;
  box-shadow: inset 0 0 0 2px #A0A0A0;
}

#dialog-text {
  margin: 0;
  font-size: 16px;
  line-height: 1.5;
  color: #181818;
}

#action-grid {
  width: 380px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 8px;
}

.action-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  font-weight: bold;
  color: #FFFFFF;
  border-radius: 8px;
  border: 3px solid #181818;
  text-shadow: 2px 2px 0px rgba(0,0,0,0.5);
  box-shadow: inset 0px 3px 0px rgba(255,255,255,0.4), 0px 4px 0px rgba(0,0,0,0.3);
  transition: all 0.1s ease;
}

.btn-luchar { background: #E04038; }
.btn-mochila { background: #E08828; }
.btn-pokemon { background: #48B048; }
.btn-huir { background: #3888E0; }

.action-btn.active-selected {
  outline: 4px solid #FFE040;
  transform: scale(1.06);
  box-shadow: inset 0px 3px 0px rgba(255,255,255,0.6), 0 0 14px #FFE040;
}

render:
var p = ctx.progress;
var params = ctx.params;

var container = ctx.root.querySelector('#battle-container');
var flashOverlay = ctx.root.querySelector('#flash-overlay');
var enemyBanner = ctx.root.querySelector('#enemy-banner');
var playerBanner = ctx.root.querySelector('#player-banner');
var actionPanel = ctx.root.querySelector('#action-panel');

var enemyName = ctx.root.querySelector('#enemy-name');
var enemyLevel = ctx.root.querySelector('#enemy-level');
var enemyHpFill = ctx.root.querySelector('#enemy-hp-fill');

var playerName = ctx.root.querySelector('#player-name');
var playerLevel = ctx.root.querySelector('#player-level');
var playerHpFill = ctx.root.querySelector('#player-hp-fill');
var playerHpNum = ctx.root.querySelector('#player-hp-num');

var dialogText = ctx.root.querySelector('#dialog-text');

if (!container) return;

// Posicionamiento y Escala General
container.style.left = params.pos_x + '%';
container.style.top = params.pos_y + '%';
container.style.transform = 'translate(-50%, -50%) scale(' + params.scale + ')';

// 1. Animación de Flash Blanco Inicial (0 a 0.12)
var flashOpacity = 0;
if (p < 0.12) {
  flashOpacity = 1 - (p / 0.12);
}
flashOverlay.style.opacity = flashOpacity;

// 2. Animaciones de Entrada (Slide In)
// Banner Enemigo desde la Izquierda (0.05 a 0.3)
var enemyP = Math.min(1, Math.max(0, (p - 0.05) / 0.25));
var enemyEase = 1 - Math.pow(1 - enemyP, 3);
var enemyXOffset = (1 - enemyEase) * -500;

// Banner Aliado desde la Derecha (0.10 a 0.35)
var playerP = Math.min(1, Math.max(0, (p - 0.10) / 0.25));
var playerEase = 1 - Math.pow(1 - playerP, 3);
var playerXOffset = (1 - playerEase) * 500;

// Panel de Acciones desde Abajo (0.15 a 0.40)
var actionP = Math.min(1, Math.max(0, (p - 0.15) / 0.25));
var actionEase = 1 - Math.pow(1 - actionP, 3);
var actionYOffset = (1 - actionEase) * 200;

actionPanel.style.transform = 'translateY(' + actionYOffset + 'px)';

// 3. Modificador de Altura de los Banners (Subir/Bajar en 2 Alturas)
var verticalHeightOffset = 0;
if (params.banner_height_state === "Nivel Alto") {
  verticalHeightOffset = -20;
} else if (params.banner_height_state === "Alternar (Animado)") {
  // Alterna tajantemente entre 0px y -20px (2 alturas discretas)
  var step = Math.floor(p * 8) % 2;
  verticalHeightOffset = (step === 1) ? -20 : 0;
}

enemyBanner.style.transform = 'translateX(' + enemyXOffset + 'px) translateY(' + verticalHeightOffset + 'px)';
playerBanner.style.transform = 'translateX(' + playerXOffset + 'px) translateY(' + verticalHeightOffset + 'px)';

// 4. Actualización de Textos e Información de Banners
if (enemyName) enemyName.textContent = params.enemy_name || '';
if (enemyLevel) enemyLevel.textContent = params.enemy_level || '';
if (playerName) playerName.textContent = params.player_name || '';
if (playerLevel) playerLevel.textContent = params.player_level || '';

// Barras de Vida y Coloración
var enemyHp = Math.min(100, Math.max(0, params.enemy_hp_pct));
if (enemyHpFill) {
  enemyHpFill.style.width = enemyHp + '%';
  enemyHpFill.style.backgroundColor = (enemyHp < 20) ? '#E04038' : (enemyHp < 50) ? '#F8B018' : '#48D068';
}

var maxHp = Math.max(1, params.player_hp_max || 1);
var currHp = Math.min(maxHp, Math.max(0, params.player_hp_curr || 0));
var playerHpPct = (currHp / maxHp) * 100;

if (playerHpFill) {
  playerHpFill.style.width = playerHpPct + '%';
  playerHpFill.style.backgroundColor = (playerHpPct < 20) ? '#E04038' : (playerHpPct < 50) ? '#F8B018' : '#48D068';
}

if (playerHpNum) {
  playerHpNum.textContent = currHp + ' / ' + maxHp;
}

// 5. Texto del Cuadro de Diálogo (Se mantiene fijo)
if (dialogText) {
  dialogText.textContent = params.action_dialog_text || '';
}

// 6. Selección de Acción con Secuencia de Duda entre Botones
var currentHighlighted = params.selected_action;

if (params.enable_doubt_seq && p >= 0.30 && p < 0.65) {
  // Cambia rápidamente entre 3 a 4 botones antes de quedar en la opción elegida
  var doubtSequence = ["MOCHILA", "POKÉMON", "HUIR", "LUCHAR"];
  var doubtP = (p - 0.30) / (0.65 - 0.30);
  var doubtIndex = Math.floor(doubtP * 4) % 4;
  currentHighlighted = doubtSequence[doubtIndex];
} else if (params.enable_doubt_seq && p < 0.30) {
  // Mientras el panel entra por abajo, resalta el primer botón por defecto
  currentHighlighted = "LUCHAR";
} else {
  // Pasado el tiempo de duda, fija la opción seleccionada por el usuario en el parámetro
  currentHighlighted = params.selected_action;
}

var btns = {
  "LUCHAR": ctx.root.querySelector('#btn-luchar'),
  "MOCHILA": ctx.root.querySelector('#btn-mochila'),
  "POKÉMON": ctx.root.querySelector('#btn-pokemon'),
  "HUIR": ctx.root.querySelector('#btn-huir')
};

Object.keys(btns).forEach(function(key) {
  if (btns[key]) {
    if (key === currentHighlighted) {
      btns[key].classList.add('active-selected');
    } else {
      btns[key].classList.remove('active-selected');
    }
  }
});
